import{_ as t,a as o,b as r,c as l,d as i}from"./chunks/2a6e358b6b012840694b.Cl-0Iz1Y.js";import{_ as s,C as n,o as h,c as m,j as e,a as c,E as u,a6 as d}from"./chunks/framework.CnPv4DE1.js";const w=JSON.parse('{"title":"专注力公式（如何掌控你的生活）","description":"","frontmatter":{"title":"专注力公式（如何掌控你的生活）","originalTitle":"The Focus Formula (How To Take Control Of Your Life)","date":"2022-12-30","originalUrl":"https://thedankoe.com/letters/the-focus-formula-how-to-take-control-of-your-life/","minutes":17,"sourceHash":"f467528b8a96605f02d625f6f9dc7249969da1ce563fec93241d1d5fdd34b9a8","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-focus-formula-how-to-take-control-of-your-life/"}]]},"headers":[],"relativePath":"letters/the-focus-formula-how-to-take-control-of-your-life.md","filePath":"letters/the-focus-formula-how-to-take-control-of-your-life.md"}'),f={name:"letters/the-focus-formula-how-to-take-control-of-your-life.md"};function g(b,p,_,k,q,P){const a=n("ArticleMeta");return h(),m("div",null,[p[0]||(p[0]=e("h1",{id:"专注力公式-如何掌控你的生活",tabindex:"-1"},[c("专注力公式（如何掌控你的生活） "),e("a",{class:"header-anchor",href:"#专注力公式-如何掌控你的生活","aria-label":'Permalink to "专注力公式（如何掌控你的生活）"'},"​")],-1)),u(a),p[1]||(p[1]=d('<p><a href="https://www.youtube.com/embed/xPpAYcPnegc?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>去年初，我偶然发现了一位被吹捧为“在世最有觉知的人”的美国哲学家。</p><p>他叫肯·威尔伯（Ken Wilber）。</p><p>我买了几本他的书，比如《<em>万物简史</em>》，然后立刻就被迷住了。</p><p>他关于整体论、意识和整合的学说，帮助我从一个高维度理解世界。一种宇宙的视角。威尔伯解答了我迫切想知道、但其他哲学家无法回答的问题。</p><p>在研究的过程中，我发现了一件有趣的事：</p><p>大卫·戴达（David Deida）和马克·曼森（Mark Manson）（《<em>男人的修行</em>》和《<em>管他妈的</em>》（<em>The Subtle Art Of Not Giving A F*ck</em>）的作者）都曾是他的学生。</p><p>戴达后来在他的书中运用这种整合模型来帮助解释性与男子气概。</p><p>在读完肯的作品后，我的写作水平也取得了显著提升。当你在建立自己的事业时，这些哲学的东西要实用得多（你以后会发现的）。</p><p>但是马克·曼森……他有一段有趣的遭遇。</p><p>曼森见证了肯·威尔伯的起落。他曾是一个坚定的学生。他热爱威尔伯的见解。</p><p>但有一天，毫无征兆地，肯突然对他的受众“翻脸”，然后消失了。</p><p>马克对威尔伯短暂跌落神坛的总结是这样的：</p><p><em>无论一个人的觉知有多高，他们终究还是人。</em></p><p>肯在休息了一段时间后，现在又重新活跃起来，并在一些更小众、细分领域的播客中露面。</p><p>虽然肯确实毫无征兆地消失过，也发表过一些有争议的言论，但我们仍然可以从他身上学到很多。尤其是当我们不急于下结论的时候。他的消失反而让人耳目一新，因为现代灵性产业和现代健身产业一样糟糕。</p><p>隐藏的缺陷让人无法看清全貌。</p><p>就像艾伦·瓦茨（Alan Watts）是一座抚慰焦虑的知识宝库一样，他也是一个酗酒的受害者。但这并不与他的哲学相矛盾。事实上，这恰恰揭示了灵性产业的欺骗性。</p><p>瓦茨是少数真正忠于自我的人之一。</p><p>我建议你阅读肯的作品来了解全貌，但我想向你介绍他所说的“全子”（holon）。</p><p>全子是万物的基本单位。</p><p>一个全子既是部分，也是整体。</p><p>就像原子本身是一个整体，但同时也是分子的一部分，以此类推，直到你触及整个宇宙。</p><p>全子向无限的方向延伸，就像木头是椅子的一部分，但同时也是树、房子和桌子的一部分。</p><p>全子是创造性解决问题的基石。</p><p>艾伦·瓦茨曾将这些称为“思想单元”。</p><p>里奥·古拉（Leo Gura）曾将这些称为“意识的虚构物”。</p><p>无限的一个快照。我们大脑创造的一种界限。能够让我们的大脑为周围世界赋予意义的无数区分之一。</p><p>将全子连接在一起的隐藏物质，是关系。</p><p>正如瓦茨所说：“存在即关系，而你正处于其正中心。”</p><p>它们不仅是物理上的，它们是万事万物。</p><p>这是一个强有力的认知。</p><p>思想、想法和情绪都是全子。</p><p>挣扎本身是一个整体，但同时也是满足感的一部分。</p><p>全子最好通过哲学沉思来理解。随便选个东西，比如你面前的一个物体，然后通过不断提问，顺着它进入一个充满发现的兔子洞。</p><p>说真的，选一个物体，然后问一系列的什么、如何、为什么、在哪里以及何时的问题。</p><p>在这里，不要将自己局限于物理世界，甚至不要局限于直接的联系。</p><p>如果我选择“蜂蜜”作为我解剖的全子，我的思维可以顺着它延伸到：</p><ul><li>酿造蜂蜜的过程</li><li>与授粉相关的蜜蜂</li><li>养蜂人以及他们是否能赚取糊口的工资</li><li>是否对蜜蜂造成了任何伤害</li><li>蜂蜜的生产和分配过程</li><li>食用蜂蜜对人类健康的影响</li><li>以及通向无限的延伸</li></ul><p>甚至那个句子中的词语也是整个句子的一部分。这个句子又是这封信件整体的一部分。这封信件又是我内容整体的一部分。以此类推。</p><p>你是一个包含你的兴趣在内的整体。兴趣是一个细分领域整体中的部分。细分领域又是一个市场整体中的部分。而市场又是社交媒体整体中的部分。</p><p>如果你在生活的任何领域中感到挣扎，那是因为你的视角没有包含使其变得完整的那些方面。这就是为什么通过保持开放的心态和不断提问来实现多视角理解如此重要。</p><h2 id="现代奴役——作为金字塔骗局的社会" tabindex="-1">现代奴役——作为金字塔骗局的社会 <a class="header-anchor" href="#现代奴役——作为金字塔骗局的社会" aria-label="Permalink to &quot;现代奴役——作为金字塔骗局的社会&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>注意全子是如何呈现层级结构的。</p><p>它们相互超越并包容。</p><p>就像人类超越并包容——或者说整合了——动物一样。随着这种超越，精神诞生了。这是心灵通过无形事物的连接。</p><p>一切事物都以层级结构构成，而层级结构分为两种。</p><p>第一种是<strong>统治者层级</strong>，正是它让“层级”这个词名声不佳。这些是由类似金字塔骗局的结构组成的。</p><p>第二种是<strong>自然层级</strong>或“自我实现层级”，也就是“一种完整性不断递增的秩序，例如：从粒子到原子到细胞再到生物体，或者从字母到单词到句子再到段落。一个层级上的整体成为了下一个层级整体的一部分。”</p><p>你可以看到人类在社会中复制这种结构时的智慧。但从宏观来看，社会其实符合统治者层级的定义。</p><p>公立学校、政府、企业工作、甚至宗教机构等社会实体，都是以这种方式构建的。</p><p>极少数的人掌握着更多的权力，位于顶端。</p><p>绝大多数的人掌握着更少的权力，位于底层。</p><p>在一个真正的金字塔骗局中，底层的投资者促成了这种不公平的权力分配。</p><p>你通过努力工作“向上爬”，但你极少能到达顶端。显然，如果底层有1000人，而顶层只有10人，那么能到达顶端的位置就只有那么多。</p><p>但是，在这里，钱并不是最大的问题。</p><p>社会金字塔骗局底层的人投资的不是金钱，<strong>他们投资的是注意力。</strong></p><p>既然人类在概念层面上生存，如果有人奴役了你的注意力，你就会认同那个层级结构。</p><p>就像人们认同他们的职位头衔一样。当别人质疑它时，他们会感到被冒犯，并心甘情愿地将注意力死死钉在上面，继续被奴役。</p><p>在现代世界中，权力来源于注意力。</p><p>在任何金字塔顶端掌握权力的人，都需要更多的集体精神能量来维持他们的权力。</p><p>正如我们之前探讨过的，人类的心智渴望秩序。</p><p>当我们能将所有的注意力集中在我们喜欢追求的任务上时，生活就会变得令人愉悦。</p><p>而随着传统价值体系崩塌带来的焦虑、不确定性和压倒性压力的增加——人们纷纷涌向这条“安全可靠”的道路，试图成为社会机器（或者你愿意的话，也可以说是社会骗局）中的一个齿轮。</p><p>我们用资本主义价值观取代了宗教价值观来保持我们的理智，对此我并不关心。我不是在这里推销意识形态，我也不认为“回归传统”是答案。我们本应该去超越并包容，或者说去进化，而不是倒退。</p><p>这就是现代奴役的定义。</p><p>它不是肉体上的，而是精神上的。</p><p>而且，这是大多数人的默认状态，除非他们意识到这一点，而这正是我在这里试图做的事情。</p><p>政治运动、企业工作和宗教意识形态靠着大众的注意力来维持，以使形成集体自我的那些理念得以存活。</p><p>从你出生的那一刻起，社会条件反射就限制了你的思维，让你和别人一样看待这个世界。</p><p>当你走出学校系统时，你就像动物一样机械化。你的行为完全出于生存本能。唯一的区别是，你试图去维护别人告诉你很重要的东西。</p><p>将注意力投资于外在的层级目标变得自动化。一个形成集体自我的统治者层级——通过依附个体身份——努力在概念上存活下来。</p><p>社会对你未来的集体愿景是获得好成绩，<em>也许</em>能找到一份高薪工作，看电视来“放松大脑”，然后<em>也许</em>能在65岁幸福地退休。这两者都伴随着潜意识里对地位、生存和认可的寻求。</p><p>由于养成了将注意力投资于外部地位游戏的习惯，这个过程会继续鼓励我们把钱浪费在豪车、豪宅和其他物质上，而完全不顾及我们自身的价值观、渴望和需求——因为我们的“自我”根本不是我们自己有意识创造出来的产物。</p><p>你可以通过创造属于你自己的<strong>自我实现层级</strong>并投入注意力，来逃离这种奴役。这是一个能为你理顺心智的层级，让你能享受生活，创造有意识的身份认同，并通过你热爱的工作影响世界。这是通过精神实现的繁衍。</p><p>你<em>可以</em>选择无所作为，但你无法逃避生存的需求。对自己的生活无所作为，恰恰是你沦为现代奴隶的原因。</p><h2 id="专注力公式——如何掌控你的生活" tabindex="-1">专注力公式——如何掌控你的生活 <a class="header-anchor" href="#专注力公式——如何掌控你的生活" aria-label="Permalink to &quot;专注力公式——如何掌控你的生活&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>如果你不知道自己想要什么，别人就会告诉你你想要什么，而且你还会深信不疑。</p><p>除非你已经消解了你的自我，并打算像僧侣一样活在永恒的当下，否则你需要一个目标。</p><p>对于一个肩负世俗责任的人来说，一生都“活在当下”是不切实际的。当下是一个工具。一份礼物。一个当你不需要采取紧急行动时可以退守的避风港。</p><p>任何不属于当下的事物，都是用于理解现实的心理建构。</p><p>既然“成功”是由一个为你梳理心智、指导行为的目标层级所决定的，你就必须创造属于你自己的层级。</p><p>让我们建立这个能让我们专注生活的结构：</p><h3 id="使命-purpose-——你的北极星" tabindex="-1">使命（Purpose）——你的北极星 <a class="header-anchor" href="#使命-purpose-——你的北极星" aria-label="Permalink to &quot;使命（Purpose）——你的北极星&quot;">​</a></h3><p>在你自我实现层级的顶端，是你的使命。</p><p>为了简单起见，你的使命将与你的愿景、毕生事业以及你生命中的任何其他宏大目标同义。</p><p>这至关重要。这是掌控你生活中最重要的一步，因为它是包含所有部分的整体。没有它，我们将要谈论的其他一切都会土崩瓦解。</p><p>但是，在谈到使命时，有几个陷阱需要注意：</p><p><strong>你的一生不会只有一个使命。</strong></p><p>它们是分阶段出现的，由浅入深。</p><p>就像你十几岁时的目标可能是为了报复前任而沉迷于健身房。</p><p>但是，你最终超越了那个目标，转而接纳了一个围绕健康、长寿和享受生活的目标。</p><p>没有错误的行动。</p><p>（不要反驳这句话。去质疑它。“错误”是由你狭隘的世界观和视角的缺乏所决定的。）</p><p>追随你的渴望，自我反省，提升你的意识，并在下一次做出更好的决定。</p><p>不要让那种完美的图景（甚至连灵性导师都会对此撒谎的图景）让你觉得你不能走错哪怕一“步”。</p><p>我那些“最糟糕”的行为造就了我人生中最美好的时刻，但这仅仅是因为我意识到了它们的后果，并相应地改变了我的行为。</p><p><strong>第一次尝试时，这一切不会一目了然。</strong></p><p>把这当作一个最小可行性目标（Minimum Viable Purpose），你会在经验中不断完善它（你需要经验来让你察觉到机会）。</p><p>如果你需要这方面的帮助，尝试创建一个反向愿景（anti-vision）。</p><p>观察大众，认清你不想要什么样的生活，然后朝着相反的方向前进。</p><p><a href="https://youtu.be/d5RKW3WSEb0" target="_blank" rel="noreferrer">我在这个短视频中对此有更多探讨</a>。</p><p><strong>你的目标会褪色。</strong></p><p>生活像一本书一样分章节展开。每一个章节都有一个由文字引向的目标。</p><p>迈入人生的新篇章时，你会感到迷茫，这很正常。</p><p>有谁说过你不应该感到迷茫吗？还是你自己对自己这么说的？“迷茫”是真实存在的。认为生命的无限性不适用于你，这种想法很愚蠢。</p><p>这就是自我反省变得至关重要的地方。</p><p>在你度过一生的过程中，除非你反省自己的行为，否则你会错过几乎所有的东西。也就是说，从你的角度来看，什么是对的，什么是错的。</p><p>当你了解了这两者，它们就会成为你下一个目标的线索。</p><p>就像拼图一样。当它们拼接在一起时，你会感受到全力以赴的牵引力。如果你一直让自己分心，这绝对不会发生。</p><p>我们如何创造一个有意义的目标？</p><p>通过提问。</p><p>如果你不知道自己想要什么，那是因为你没有问对问题。</p><p>高质量的问题决定了你生活的质量，因为你的理解质量取决于你得到的答案的质量。</p><p>你不会立刻得到这些问题的答案。</p><p>你问自己一个问题 &gt; 在生活中继续前行 &gt; 并反省你的经验以寻找答案。</p><p>把这些问题当作注意力的锚点。把这些问题摆在明面上，随着时间的推移，你的大脑就会自然而然地去留意答案：</p><ul><li>我在生活中真正想要的是什么？</li><li>什么对我来说是重要的？</li><li>最高版本的我是什么样子的？</li><li>我理想中的一天是什么样子的？</li><li>为了实现这些，我必须完成什么？</li><li><em>这能解决世界上的某个问题吗？什么样的产品或服务能与两者相契合？</em></li><li>我目标的下一个阶段是什么？</li></ul><p>把。这些。写下来。</p><h3 id="过程-–-对精通的追求" tabindex="-1">过程 – 对精通的追求 <a class="header-anchor" href="#过程-–-对精通的追求" aria-label="Permalink to &quot;过程 – 对精通的追求&quot;">​</a></h3><p><img src="'+r+'" alt=""></p><p>能够让你实现那个目标的过程是什么？</p><p>你所拥有的每一个目标——从本质上讲——都伴随着一个后续的目标层级，一直向下延伸到一个微小的、与行为相关的目标，比如写下一篇文章的第一个字。</p><p>你用来实现目标的过程、系统或策略，是你防止大脑陷入混乱的方法。</p><p>当你理解了系统，它们就能帮助你的大脑维持秩序。单凭这一点就能让你的生活乐趣翻十倍。</p><p>问题在于，人们认为只要“随性发挥（winging it）”就万事大吉了。</p><p>如果你不把这个目标层级放在脑海的首要位置，你就会把太多的精神能量——通过注意力转移——浪费在那些让你从过程中分心的事情上。</p><p>通过写下 10 年、1 年、每月、每周和每日的目标，让这些目标变得清晰可见。</p><p>再次强调，尽可能具体。</p><p>既然这些目标被写下来了，你就会随着经验的积累不断完善它们。这本身就是一个能让你大脑井然有序的过程。</p><p>精通的过程是分阶段的。</p><p>初级、中级和高级，这与你实现愿景必须掌握的技能息息相关。</p><p>你必须清楚自己处于哪个阶段，以及你需要做什么才能晋升到下一个阶段。</p><p>每个阶段都会有属于自己的一套撬动杠杆的行动，用来打磨完善你的过程。</p><p>作为一个商业新手，你的杠杆可能在于学习营销和销售基础、撰写内容，以及在网上建立人脉。</p><p>作为一个中级者，你的杠杆可能在于打造一个产品，从而将你的受众变现。你可以开始逐渐减少对外部资源学习的依赖。</p><p>作为一个专家，你的杠杆可能在于做你喜欢的事、重新利用你最棒的作品，并实现触达渠道的多元化。</p><p>再说一遍，把所有这些都写下来。</p><p>年度、月度、每周和每日目标，配上能推动你实现目标的撬动杠杆的行动。</p><h3 id="优先级-–-做出更好的决策" tabindex="-1">优先级 – 做出更好的决策 <a class="header-anchor" href="#优先级-–-做出更好的决策" aria-label="Permalink to &quot;优先级 – 做出更好的决策&quot;">​</a></h3><p><img src="'+l+'" alt=""></p><p>首先，这概括了我们刚刚讨论过的撬动杠杆的行动。</p><p>这些最好被设定为绩效目标（而不是虚荣目标）。</p><p>不要把目标定在无法控制的“每天涨 50 个粉丝”上，而是将目标定为写 3 篇可能<em>带来</em>每天涨 50 个粉丝的帖子。</p><p>不要把目标定为写一篇“文笔优美的文章”，而是将目标定为写 1000 个字（之后你可以回过头来编辑修改）。</p><p>具体化有助于减少行动的阻力，因为你能直接控制结果。</p><p>此时此刻的你，就是你过去所有选择的化身。这些选择不仅仅是物质上的……还包括精神、财务和心灵上的。</p><p>可以确信地说，你 10 年后的生活，将是你今天、明天以及未来选择的化身。</p><p>当你有一个<em>目标</em>和<em>过程</em>让你的注意力在其中来回切换时，做出更好的决策会更容易，但这还不够。</p><p>以下是如何做出更好的决策：</p><p><strong>把你的目标放在脑海的首要位置。</strong></p><p>这将帮助你在噪音中过滤出信号。如果它对你的愿景没有帮助，它就不重要（除非你被别人说服它很重要）。</p><p>这一切都需要时间。</p><p>你的信噪比（重要信号对比分心噪音）会随着你的进步而提高。</p><p><strong>获得多视角的理解。</strong></p><p>不要把你的思想锁死在一个视角里。尝试从多个角度看问题。</p><p>你的视角是基于你的身份认同的。</p><p>随着时间的推移，我们要努力采纳一种宇宙视角。如果你以宇宙自居，人类的问题就变得微不足道，你就可以开始致力于寻找创造性的解决方案来推动人类进步。</p><p>但是，这需要时间。</p><p>作为人类，我们为了让自己当下的身份认同存活而努力。你无法逃脱生存法则，我们体内依然有着动物的天性。但是，我们可以努力让一个更“开悟”的身份存活下来，比如宇宙、人类，或者是已达成自我实现的那个你。</p><p><em>如果你的视角是构成你身份认同整体的一部分，你就可以通过超越并包容不同视角来进化，直到你成为整个宇宙。</em></p><p>从认同未来的自己开始，未来的你会如何处理这些情况？</p><p>如果你能做到这一点，做决策就会变成自发的，因为你在试图保全你更高层级自我的理念。</p><p>视角的话题非常深奥。我正计划为此再写一封信，但核心问题是：</p><p><em>你该如何看待眼前的情况，才能让你以一种有助于采取行动的方式去感知它？</em></p><p><strong>以一种让你能够与目标保持一致去行动的方式来感知情况。</strong></p><p>问题只有在你把它解读为问题时，它才是问题。</p><p>如果你不想起床，退后一步，想想你那微不足道的问题。</p><p>这个世界上有的人没有双腿。如果没有帮助，他们根本下不了床。</p><p>有些人早上连床都没有，或者根本没有食物可煮。</p><p>采纳他们的视角，透过他们的镜头来解读你的问题，你觉得他们他妈的会在乎你是不是“不想”起床吗？</p><p>你有一个需要去实现的目标。</p><p>动起来。</p><h3 id="意识" tabindex="-1">意识 <a class="header-anchor" href="#意识" aria-label="Permalink to &quot;意识&quot;">​</a></h3><p>意识状态就是一切。</p><p>通过社会规训——为了让我们能在社会中运转——大多数人都有着狭隘的世界观。</p><p>这种世界观包含了他们的信仰，信仰影响思想，思想影响情绪，情绪影响注意力。</p><p>注意力影响行为。</p><p>如果你只知道社会为你铺设的那条路，你的注意力就会被死死钉在那条路上，并被奴役以换取生存。</p><p>一份稳定的薪水。一个骨子里跟你毫无共同点可言的配偶。当然，还有太多太多的责任……这样你就无法把注意力投入到你自己的事情上了。</p><p>社会非常清楚人类的机械本性。</p><p>通过追求你自己的事业，随着时间的推移，一切都会变得更容易。</p><p>这本来就不是一个轻松的过程。</p><p>有些人甚至会认为，提升你的意识就是生命的意义。</p><p>你通过质疑一切、觉察到一个潜在的未来，并学会终生应对这些起起落落来提升你的意识。</p><p>你通过创造一个整体的身份认同（比如人类或宇宙），并扩展你的思想以体现那种视角，来进一步提升你的意识。</p><p>你的行为会随之跟上，真正的问题会显现出来，而你可以通过创造力来解决它们。</p><h3 id="挑战-–-智慧与进化的源泉" tabindex="-1">挑战 – 智慧与进化的源泉 <a class="header-anchor" href="#挑战-–-智慧与进化的源泉" aria-label="Permalink to &quot;挑战 – 智慧与进化的源泉&quot;">​</a></h3><p><img src="'+i+'" alt=""></p><p>你的个人自我实现层级——目标、过程和优先级——应该是具有挑战性的。</p><p>许多传统的目标一开始是有挑战性的，但这种挑战很快就会消退。而且，这些挑战并非<em>你</em>真正想去承担的。</p><p>挑战会进一步聚焦注意力。这有助于消除让你偏离正轨的干扰因素。</p><p>你的过程为了实现愿景而呈现的每一个后续目标，都将要求你成长。</p><p>也就是说，你必须投资于自身的教育，以获取迎接该目标挑战所需的技能组合。</p><p>学习的源泉是挣扎，而不是死记硬背。</p><p>这不是一份企业打工，不是到了阶梯的某一梯级你就会停止进化。要避免没有进步的盲目重复。</p><h3 id="清晰度-–-随时间的推移进行自我修正" tabindex="-1">清晰度 – 随时间的推移进行自我修正 <a class="header-anchor" href="#清晰度-–-随时间的推移进行自我修正" aria-label="Permalink to &quot;清晰度 – 随时间的推移进行自我修正&quot;">​</a></h3><p>如果建立你的目标、过程和优先级对你来说并不容易，<em>不要陷入快速解决问题的心态</em>_._</p><p>这一切都不容易。</p><p>这一切都不是一蹴而就的。</p><p>这一切在刚开始时都不会一目了然。</p><p>你可以预测未来，但不可能有完美的预测。</p><p>我们谈论的是一生（LIFE），而不是一天（DAY）。</p><p>这需要时间，如果你还没这么做，回去尽你最大的努力把这一切都写下来。</p><p>自我反省将是你这段旅程中最好的朋友。</p><p>每个月，回去看看你写下的东西。</p><p>反省什么是对的，什么是错的。</p><p>但你要明白，在当下，并没有绝对正确或错误的选择。你不可能100%确切地知道你的行为会导致什么结果。要习惯生活这种不确定的本质。</p><p>经验是你随着时间的推移完善目标的方式。这就是你如何（在你的能力范围内）创造属于你自己的确定性。</p><p>如果你不犯错，你就不知道该改进什么。</p><p>觉察会衍生出更多的觉察。</p><h3 id="对齐-–-外在潜力与内在进步" tabindex="-1">对齐 – 外在潜力与内在进步 <a class="header-anchor" href="#对齐-–-外在潜力与内在进步" aria-label="Permalink to &quot;对齐 – 外在潜力与内在进步&quot;">​</a></h3><p>顶层金字塔——目标、过程、优先级——为你创造了一个潜在的现实，让你通过日常的抉择去创造。</p><p>它们负责系统外（extrapersonal）的神经递质，比如多巴胺。</p><p>底层金字塔——意识、挑战和清晰度——在你的大脑中创造出日益增强的秩序。</p><p>它们负责产生内啡肽等近身神经递质。</p><p>当这些对齐时，你就会在大脑中制造出一种持续循环的神经化学鸡尾酒。你会更容易生活在某种程度的心流状态中，把注意力集中在未来，几乎没有什么能让你偏离正轨。</p><p>你通过注意力来对齐这些金字塔。</p><p>意思是，你必须腾出时间来为你的梦想努力，反思你的进展，并完善你的策略。</p><p>把无脑消费替换成构建未来。</p><p>生活在你为自己创造的心理现实中。</p><h3 id="这是你的现实-——-关于专注力公式的一点说明" tabindex="-1">这是你的现实 —— 关于专注力公式的一点说明 <a class="header-anchor" href="#这是你的现实-——-关于专注力公式的一点说明" aria-label="Permalink to &quot;这是你的现实 —— 关于专注力公式的一点说明&quot;">​</a></h3><p>这不仅适用于你的生活。</p><p>它适用于你做的任何事情。</p><p>如果你正在建立一项副业，你需要一个目标、过程、优先级以及其他一切。</p><p>如果你正在写一篇文章，你也需要同样的东西。甚至这篇文章的结构也是一样的。你通过极具说服力的实现层级结构（actualization hierarchies）与外部世界进行沟通。</p><p>这是一个能在生活的宏观与微观层面上让你发挥最高潜能的元公式。</p><p>最后，这就是你的现实。</p><p>当分心发生时，你所创造的专注力公式就是你将注意力重新拉回的地方。</p><p>在你自己的小世界里埋头苦干，瞄准你的目标，别人的意见就不再有分量了。</p><p>专注起来。</p><p>戴上耳机，拉起兜帽，任凭他人批评，专心为自己和这个世界创造一个更好的未来。</p><p>– Dan Koe</p><hr><p><a href="/en/letters/the-focus-formula-how-to-take-control-of-your-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',237))])}const A=s(f,[["render",g]]);export{w as __pageData,A as default};
